function openCoopPicker(type,index){coopPickerTarget={type,index};pickerPurpose=type==='deck'&&index%5>0?'coopDeckRestricted':'character';$('pickerTitle').textContent=type==='enemy'?'敵キャラを選択':'味方キャラを選択';$('pickerSearch').value='';ensurePickerTools();renderPicker();$('picker').hidden=false}
