function chooseCoopCharacter(c){let t=coopPickerTarget;if(!t)return false;if(t.type==='enemy'){let e=coopEnemies[t.index],d=c.details||{};e.character=c;e.hp=Number(d.hp||0);e.attribute=norm(d.attribute)}else{let r=Math.floor(t.index/5),s=t.index%5,key=coopCharacterKey(c);for(let slot=0;slot<COOP_SLOTS;slot++)if(slot!==s&&coopCharacterKey(coopDecks[r][slot])===key)coopDecks[r][slot]=null;coopDecks[r][s]=c;syncCoopVisibleRows()}coopPickerTarget=null;$('picker').hidden=true;renderCoopEnemies();renderCoopDecks();saveCoopState();return true}
function effectDuration(e){let n=Number(e?.duration);return Number.isFinite(n)&&n>0?Math.floor(n):1}
function shortenValue(e){let v=raw(e?.value??e?.amount??e?.['効果量']);return Number.isFinite(v)?Math.max(0,Math.floor(v)):0}
function coopStructuredEffectValid(e){return !!e&&e.needsReview!==true&&typeof e.effect==='string'&&e.effect.length>0}
function coopScopeIsSelf(e){return /自身|自分/.test(String(e?.applier??''))}
function coopScopeIsLeader(e){return /リーダー/.test(String(e?.applier??''))}
function coopAllyMatchesEffect(e,owner,recipient,source,ownerRow=null,recipientRow=null,recipientSlot=null){if(!recipient)return false;if(coopScopeIsSelf(e)){if(ownerRow!=null&&recipientRow!=null&&ownerRow!==recipientRow)return false;if(recipientSlot!=null&&recipientSlot<source)return false}if(coopScopeIsLeader(e)&&recipientRow!==0)return false;return matches(norm(recipient.details?.attribute),e?.applierAttribute??e?.applier??'全')}
function coopEffectApplies(x,attacker,enemy){return coopAllyMatchesEffect(x.effect,x.owner,attacker,x.source,x.deckRow,x.recipientRow,x.recipientSlot)&&targetMatches(x.effect,enemy.attribute)}
function coopTimelineKey(row,source){return `${row}:${source}`}
