  const merge=(base,items)=>{let map=new Map(base);for(let item of items||[]){let key=coopProposalDeckKey(item.ids||coopProposalDeckIds(coopProposalItemDeck(item)));if(key&&!map.has(key))map.set(key,item)}return map};
